\section{Introduction}

Iterated maps $x_{n+1} = f(x_n)$ are the backbone of numerical analysis, dynamical
systems, and many learning algorithms. The decisive structural question for any such
map is whether it possesses an attracting fixed point and, if so, how fast the
iteration converges to it. The classical answer is the Banach fixed-point theorem: a
contraction on a complete metric space has a unique fixed point, reached
geometrically from any starting point.

This paper carries out that program concretely for the \emph{EML operator}
\[
  f(x) = e^{a}\log(bx + c), \qquad a, b, c \in \R,
\]
a composition of an inner affine map $x \mapsto bx + c$, the natural logarithm, and
an outer multiplicative scaling by $e^a > 0$. The operator is a natural single-layer
abstraction of exp-log activation pipelines. Our contributions are: a clean
structural hypothesis bundle (Definition~\ref{def:cert}); a self-contained
derivation of existence, uniqueness, and global convergence
(Theorems~\ref{thm:uniq}--\ref{thm:exist}); the \emph{certified geometric rate}
(Theorems~\ref{thm:apriori}--\ref{thm:packaged}, Corollary~\ref{cor:tendsto}); a
fully verified concrete instance (Theorem~\ref{thm:concrete}); and an existence
result outside the contraction regime via the intermediate value theorem
(Theorem~\ref{thm:ivt}).

\section{Definitions}

\begin{definition}[EML operator]
For parameters $a, b, c \in \R$, the \emph{exp-log operator} is
\[
  f_{a,b,c}(x) = e^{a}\,\log(bx + c),
\]
defined wherever $bx + c > 0$. We write $f$ when the parameters are fixed.
\end{definition}

\begin{definition}[Iteration sequence]
Given a starting point $x_0$, the \emph{EML iteration} is
\[
  x_0 \text{ given}, \qquad x_{n+1} = f(x_n) = e^{a}\log(bx_n + c).
\]
\end{definition}

\begin{definition}[Contraction certificate]\label{def:cert}
An \emph{EML contraction certificate} on a closed interval $[\lo, \hi]$ consists of
parameters $a,b,c$, endpoints $\lo < \hi$, and a ratio $\rho$ with $0 \le \rho < 1$,
satisfying:
\begin{itemize}
  \item \textbf{(Positivity)} $bx + c > 0$ for all $x \in [\lo, \hi]$;
  \item \textbf{(Invariance)} $f(x) \in [\lo, \hi]$ for all $x \in [\lo, \hi]$;
  \item \textbf{(Derivative bound)} $\left|\dfrac{e^{a}\,b}{bx + c}\right| \le \rho$
        for all $x \in [\lo, \hi]$.
\end{itemize}
\end{definition}

\section{Analytic foundations}

\begin{proposition}[Derivative formula]\label{prop:deriv}
Wherever $bx + c > 0$, the operator is differentiable with
\[
  f'(x) = \frac{e^{a}\,b}{bx + c}.
\]
\end{proposition}

\begin{proof}[Proof sketch]
$f = e^a \cdot \log \circ (x \mapsto bx+c)$. The chain and constant-multiple rules
give $f'(x) = e^a \cdot \frac{1}{bx+c}\cdot b$; positivity makes the inner argument
nonzero, validating the logarithm's derivative.
\end{proof}

The numerator $e^a b$ is constant while $bx + c$ increases in $x$ (for $b>0$), so
$|f'|$ is decreasing and a uniform bound is attained at the endpoint with the
smallest denominator.

\begin{proposition}[Fixed-point equation]\label{prop:fp}
If $f(\xstar) = \xstar$ then $\xstar = e^{a}\log(b\xstar + c)$. If additionally
$\xstar > 0$ and $b\xstar + c > 0$, then $b\xstar + c > 1$.
\end{proposition}

\begin{proof}[Proof sketch]
The first claim restates the fixed-point condition. For the second,
$\xstar = e^a\log(b\xstar+c) > 0$ with $e^a > 0$ forces $\log(b\xstar+c) > 0$, i.e.
$b\xstar + c > 1$.
\end{proof}

\section{Contraction, uniqueness, and convergence}

\begin{lemma}[Lipschitz bound]\label{lem:lip}
Under positivity and the derivative bound, $f$ is $\rho$-Lipschitz on $[\lo,\hi]$:
\[
  |f(x) - f(y)| \le \rho\,|x - y| \qquad (x, y \in [\lo,\hi]).
\]
\end{lemma}

\begin{proof}[Proof sketch]
The interval is convex, $f$ is differentiable on it (Proposition~\ref{prop:deriv}),
and $|f'| \le \rho$ there. The mean value inequality converts the pointwise
derivative bound into the global Lipschitz estimate.
\end{proof}

\begin{theorem}[Uniqueness]\label{thm:uniq}
Under a certificate, $f$ has at most one fixed point in $[\lo,\hi]$.
\end{theorem}

\begin{proof}[Proof sketch]
If $f(x_1)=x_1$ and $f(x_2)=x_2$, Lemma~\ref{lem:lip} gives
$|x_1 - x_2| \le \rho|x_1 - x_2|$; with $\rho < 1$ this forces $x_1 = x_2$.
\end{proof}

\begin{lemma}[Trapping]\label{lem:trap}
If $x_0 \in [\lo,\hi]$ and invariance holds, then $x_n \in [\lo,\hi]$ for all $n$.
\end{lemma}

\begin{proof}[Proof sketch]
Induction: base case $x_0$; the step applies invariance to $x_n$.
\end{proof}

\begin{lemma}[Geometric step decay]\label{lem:decay}
For $x_0 \in [\lo,\hi]$, $\;|x_{n+1} - x_n| \le \rho^{n}\,|x_1 - x_0|$ for all
$n \ge 0$.
\end{lemma}

\begin{proof}[Proof sketch]
Induction using Lemma~\ref{lem:lip} on $x_n, x_{n-1}$ (both in $[\lo,\hi]$ by
Lemma~\ref{lem:trap}):
$|x_{n+1}-x_n| \le \rho|x_n - x_{n-1}| \le \rho^{n}|x_1-x_0|$.
\end{proof}

\begin{lemma}[Cauchy]\label{lem:cauchy}
The iteration $(x_n)$ is Cauchy.
\end{lemma}

\begin{proof}[Proof sketch]
By Lemma~\ref{lem:decay} the consecutive distances are dominated by the convergent
geometric series $|x_1-x_0|\sum \rho^n$ (since $\rho < 1$).
\end{proof}

\begin{theorem}[Existence and global convergence]\label{thm:exist}
Under a certificate, for every $x_0 \in [\lo,\hi]$ there exists
$\xstar \in [\lo,\hi]$ with $f(\xstar) = \xstar$ and $x_n \to \xstar$.
\end{theorem}

\begin{proof}[Proof sketch]
By Lemma~\ref{lem:cauchy} and completeness of $\R$, $x_n \to \xstar$. The interval
is closed and contains all $x_n$ (Lemma~\ref{lem:trap}), so $\xstar \in [\lo,\hi]$,
where $f$ is continuous. Passing to the limit in $x_{n+1} = f(x_n)$ yields
$f(\xstar) = \xstar$; uniqueness is Theorem~\ref{thm:uniq}.
\end{proof}

\section{The certified geometric rate}

\begin{theorem}[A priori error estimate]\label{thm:apriori}
Under a certificate, with limit $\xstar$ from Theorem~\ref{thm:exist},
\[
  |x_n - \xstar| \;\le\; |x_1 - x_0|\,\frac{\rho^{n}}{1 - \rho} \qquad (n \ge 0).
\]
\end{theorem}

\begin{proof}[Proof sketch]
From Lemma~\ref{lem:decay},
\[
  |x_n - \xstar| \le \sum_{k \ge n} |x_{k+1} - x_k|
  \le |x_1 - x_0|\sum_{k\ge n}\rho^k = |x_1 - x_0|\,\frac{\rho^n}{1-\rho}.
\]
\end{proof}

\begin{theorem}[Certified rate, packaged]\label{thm:packaged}
Under a certificate there is a fixed point $\xstar \in [\lo,\hi]$ with
$x_n \to \xstar$ and, for all $n$,
$|x_n - \xstar| \le |x_1 - x_0|\,\rho^n/(1-\rho)$.
\end{theorem}

\begin{corollary}[Genuine $O(\rho^n)$ convergence]\label{cor:tendsto}
The error envelope $|x_1 - x_0|\,\rho^n/(1-\rho) \to 0$ as $n \to \infty$.
\end{corollary}

\begin{proof}[Proof sketch]
$\rho^n \to 0$ since $0 \le \rho < 1$; the prefactor is constant.
\end{proof}

The estimate is an engineering certificate: its right-hand side depends only on the
first step $|x_1 - x_0|$ and on $\rho$. To guarantee $|x_n - \xstar| \le \varepsilon$
it suffices to take
\[
  n \ge \frac{\log\!\big(\varepsilon (1-\rho)/|x_1 - x_0|\big)}{\log \rho},
\]
computable before the iteration is run.

\section{A concrete, non-vacuous instance}

\begin{construction}\label{con:concrete}
Take $a = 1$, $b = 1$, $c = 100$, interval $[0, 20]$, ratio $\rho = 1/30$. The
operator is $f(x) = e\,\log(x+100)$.
\end{construction}

\noindent\textbf{Verification.}
\begin{itemize}
  \item \emph{Positivity:} on $[0,20]$, $x + 100 \ge 100 > 0$.
  \item \emph{Derivative bound:} $f'(x) = e/(x+100) \le e/100 < 3/100 < 1/30$,
        using $e < 3$.
  \item \emph{Invariance:} $e\log(x+100) \ge e\log(100) > 0$ and
        $e\log(x+100) \le e\log(120) < 3\cdot 5 = 15 < 20$, using $\log(120) < 5$
        (from $e^5 > 2.7^5 > 120$ and $e > 2.7$).
\end{itemize}
Since $a=1$, $e^a = e > 1$, so the operator is a genuine exp-log composition.

\begin{theorem}[End-to-end certified convergence]\label{thm:concrete}
For every $x_0 \in [0,20]$ there exists $\xstar \in [0,20]$ with $f(\xstar)=\xstar$,
$x_n \to \xstar$, and for all $n$,
\[
  |x_n - \xstar| \le |x_1 - x_0|\,\frac{(1/30)^n}{1 - 1/30}.
\]
\end{theorem}

\begin{proof}[Proof sketch]
The Construction discharges all hypotheses of Definition~\ref{def:cert}; apply
Theorem~\ref{thm:packaged}.
\end{proof}

Numerically $\xstar \approx 12.85$, and each iteration reduces the remaining error
by a factor $\approx 0.0333$.

\section{Existence outside the contraction regime}

\begin{theorem}[IVT existence for $b=1$, $c=2$]\label{thm:ivt}
For every $a$ with $0 < a < \tfrac12$, the operator $f(x) = e^{a}\log(x + 2)$ has a
fixed point $\xstar \in (1,3)$; in particular $\xstar > 0$.
\end{theorem}

\begin{proof}[Proof sketch]
Let $g(x) = e^a\log(x+2) - x$, continuous on $[1,3]$. Then $g(1) = e^a\log 3 - 1 > 0$
(since $\log 3 > 1$, $e^a \ge 1$), while $g(3) = e^a\log 5 - 3 < 0$ for $a < \tfrac12$
(since $e^{1/2}\log 5 < 1.7\cdot 1.7 < 3$). The intermediate value theorem gives a
zero in $(1,3)$, a fixed point of $f$.
\end{proof}

As $a \to 0$ this fixed point tends to the solution of $\xstar = \log(\xstar + 2)$,
namely $\xstar \approx 1.146$.

\section{Discussion}

The concrete instance succeeds by \emph{slack engineering}: a large $c$ relative to
the interval keeps $bx+c$ large (small $|f'|$, easy derivative bound) and above $1$
($\log$ positive, invariance forced by slow logarithmic growth). The opposite regime
is genuinely obstructed: for $b = 1$ and small $c \in (0,1)$, $\log(x+c)$ can be
negative, candidate intervals fail to be invariant, and the slope near the lower
endpoint can exceed $1$. No closed interval inside $\{x : x + c > 0\}$ is
simultaneously invariant and contracting there. This explains why the literal
small-$c$ test case is hard, and motivates the large-$c$ formulation proved here.

\section{Future work}

Sharpen $\rho$ to the spectral value $|f'(\xstar)|$; derive an a-posteriori residual
stopping criterion $|x_n - \xstar| \le \rho/(1-\rho)\,|x_n - x_{n-1}|$; establish
real-analytic dependence $\xstar(a)$ with $d\xstar/da = \xstar/(1 - f'(\xstar))$; and
give a sharp characterisation of the small-$c$ invariant-interval obstruction.

\section{Conclusion}

We have given a complete, self-contained treatment of the EML fixed-point iteration:
a structural hypothesis bundle, existence and uniqueness, global convergence, and a
fully explicit, computable $O(\rho^n)$ a priori error estimate. A concrete instance,
$f(x) = e\log(x+100)$ on $[0,20]$ with $\rho = 1/30$, certifies non-vacuity, and an
intermediate-value argument extends existence beyond the contraction regime.

